import{_ as i,o as n,c as e,a2 as t}from"./chunks/framework.CqpfiAoK.js";const o=JSON.parse('{"title":"Hukum Kerja Simbiosis","description":"","frontmatter":{},"headers":[],"relativePath":"id/41-共生劳动法.md","filePath":"id/41-共生劳动法.md","lastUpdated":null}'),r={name:"id/41-共生劳动法.md"};function k(s,a,u,d,m,l){return n(),e("div",null,[...a[0]||(a[0]=[t('<h1 id="hukum-kerja-simbiosis" tabindex="-1">Hukum Kerja Simbiosis <a class="header-anchor" href="#hukum-kerja-simbiosis" aria-label="Permalink to &quot;Hukum Kerja Simbiosis&quot;">​</a></h1><table tabindex="0"><thead><tr><th>Proyek</th><th>Konten</th></tr></thead><tbody><tr><td>Nomor dokumen</td><td>41</td></tr><tr><td>Modul</td><td>Sistem Hukum dan Kerangka Tata Kelola</td></tr><tr><td>Kata kunci utama</td><td>Kerja Simbiosis, Lebih Banyak Kerja Lebih Banyak Hasil, Hak Kerja, Kontrak Produksi Bersama, Anti-eksploitasi</td></tr></tbody></table><h2 id="i-tujuan-legislasi-dan-prinsip-dasar" tabindex="-1">I. Tujuan Legislasi dan Prinsip Dasar <a class="header-anchor" href="#i-tujuan-legislasi-dan-prinsip-dasar" aria-label="Permalink to &quot;I. Tujuan Legislasi dan Prinsip Dasar&quot;">​</a></h2><p>《Hukum Kerja Simbiosis》 adalah salah satu hukum inti dalam sistem hukum peradaban simbiosis jangkar, sejajar dengan 《Konstitusi Simbiosis》, bertujuan untuk mengatur semua aktivitas kerja dan kontribusi di dalam Hengyuanzhou, menetapkan tatanan distribusi &quot;lebih banyak kerja lebih banyak hasil, tumbuh sendiri&quot;, dan memberantas akar eksploitasi predator dari tingkat hukum.</p><p>Hukum ini menetapkan prinsip dasar berikut:</p><table tabindex="0"><thead><tr><th>Prinsip</th><th>Isi</th></tr></thead><tbody><tr><td>Prinsip Martabat Kerja</td><td>Semua kerja legal dilindungi hukum, martabat pribadi pekerja tidak boleh dilanggar</td></tr><tr><td>Prinsip Lebih Banyak Kerja Lebih Banyak Hasil</td><td>Imbalan kerja terkait langsung dengan jumlah kontribusi, semakin besar kontribusi semakin tinggi hasil, dilarang mendapatkan hasil tanpa kerja</td></tr><tr><td>Prinsip Kerja Sukarela</td><td>Dilarang kerja paksa dan perbudakan, pekerja memiliki hak untuk memilih secara bebas isi dan cara kerja</td></tr><tr><td>Prinsip Imbalan Adil</td><td>Upah sama untuk kerja sama, dilarang diskriminasi imbalan berdasarkan ras, tingkat kultivasi, asal-usul</td></tr><tr><td>Prinsip Jaminan Kerja</td><td>Negara dan peradaban memiliki kewajiban untuk memberikan lingkungan kerja yang aman dan jaminan sosial dasar bagi pekerja</td></tr><tr><td>Prinsip Kerja Sama Simbiosis</td><td>Mendorong kerja sama dan saling membantu antar pekerja, menentang persaingan jahat dan permainan zero-sum</td></tr></tbody></table><h2 id="ii-hak-dasar-pekerja" tabindex="-1">II. Hak Dasar Pekerja <a class="header-anchor" href="#ii-hak-dasar-pekerja" aria-label="Permalink to &quot;II. Hak Dasar Pekerja&quot;">​</a></h2><p>Hukum Kerja Simbiosis memberikan kepada semua makhluk yang memiliki kemampuan kerja di dalam Hengyuanzhou hak-hak berikut:</p><ol><li><strong>Hak Ketenagakerjaan Setara</strong>: Tidak ada makhluk yang didiskriminasi karena ras, tingkat kultivasi, asal-usul, jenis kelamin, dll. dalam proses melamar pekerjaan dan dipekerjakan.</li><li><strong>Hak Memilih Pekerjaan Secara Bebas</strong>: Pekerja memiliki hak untuk memilih profesi, jabatan, dan tempat kerja sesuai dengan keinginan dan kemampuannya sendiri, dan memiliki hak untuk mengubah profesi sesuai hukum.</li><li><strong>Hak Imbalan yang Wajar</strong>: Pekerja memiliki hak untuk menerima imbalan yang sesuai dengan kontribusi kerjanya, imbalan tidak boleh di bawah standar jaminan minimum yang ditetapkan peradaban.</li><li><strong>Hak Istirahat dan Cuti</strong>: Pekerja memiliki hak untuk menerima pengaturan waktu kerja yang wajar dan cuti teratur, dilarang memperpanjang waktu kerja tanpa batas.</li><li><strong>Hak Keamanan Kerja</strong>: Pekerja memiliki hak untuk bekerja di lingkungan yang aman dan sehat, pemberi kerja harus menyediakan kondisi perlindungan kerja yang memenuhi standar.</li><li><strong>Hak Pelatihan Profesional</strong>: Pekerja memiliki hak untuk menerima pelatihan keterampilan profesional dan bimbingan kultivasi, pemberi kerja dan negara memiliki kewajiban untuk menyediakan sumber daya pelatihan.</li><li><strong>Hak Berorganisasi dan Bernegosiasi</strong>: Pekerja memiliki hak untuk membentuk atau bergabung dengan asosiasi pekerja sesuai hukum, dan memiliki hak untuk membela hak-haknya sendiri melalui negosiasi kolektif.</li><li><strong>Hak Pengaduan dan Pemulihan</strong>: Pekerja, ketika hak kerjanya dilanggar, memiliki hak untuk mengajukan pengaduan dan gugatan kepada lembaga arbitrase kerja dan Pengadilan Simbiosis.</li></ol><h2 id="iii-legalisasi-mekanisme-kontrak-produksi-bersama" tabindex="-1">III. Legalisasi Mekanisme Kontrak Produksi Bersama <a class="header-anchor" href="#iii-legalisasi-mekanisme-kontrak-produksi-bersama" aria-label="Permalink to &quot;III. Legalisasi Mekanisme Kontrak Produksi Bersama&quot;">​</a></h2><p>Mekanisme kontrak produksi bersama adalah sistem inti distribusi sumber daya peradaban simbiosis jangkar, dan 《Hukum Kerja Simbiosis》 menetapkannya dalam bentuk hukum:</p><ul><li><strong>Subjek Kontrak</strong>: Setiap makhluk yang memiliki kemampuan kerja dapat menjadi subjek kontrak, baik individu maupun kolektif dapat mengontrak.</li><li><strong>Isi Kontrak</strong>: Termasuk tetapi tidak terbatas pada pengembangan sumber daya kultivasi, pemeliharaan bidang, pewarisan pengetahuan, penelitian dan pengembangan teknologi, layanan publik, dll.</li><li><strong>Jangka Waktu Kontrak</strong>: Ditentukan sesuai dengan sifat isi kontrak, kontrak jangka pendek adalah satu hingga tiga tahun, kontrak jangka panjang adalah lima hingga dua puluh tahun, dapat diperpanjang setelah berakhir.</li><li><strong>Distribusi Hasil</strong>: Hasil kontraktor terkait langsung dengan produksinya, sebagian dari produksi diserahkan ke akumulasi publik, sisanya menjadi milik kontraktor.</li><li><strong>Mekanisme Keluar</strong>: Kontraktor memiliki hak untuk keluar dari kontrak setelah pemberitahuan sebelumnya dalam jangka waktu yang wajar, tidak boleh dipaksa terikat dalam hubungan kontrak.</li><li><strong>Penyelesaian Sengketa</strong>: Sengketa kontrak diselesaikan secara prioritas melalui arbitrase kerja, yang tidak puas dengan hasil arbitrase dapat menggugat ke Pengadilan Simbiosis.</li></ul><h2 id="iv-perlindungan-kerja-khusus" tabindex="-1">IV. Perlindungan Kerja Khusus <a class="header-anchor" href="#iv-perlindungan-kerja-khusus" aria-label="Permalink to &quot;IV. Perlindungan Kerja Khusus&quot;">​</a></h2><p>Untuk memenuhi kebutuhan khusus dari berbagai bentuk kehidupan di dalam Hengyuanzhou, hukum ini menetapkan sistem perlindungan kerja khusus:</p><table tabindex="0"><thead><tr><th>Kelompok yang Dilindungi</th><th>Tindakan Perlindungan Khusus</th></tr></thead><tbody><tr><td>Kultivator Pemula</td><td>Tidak boleh ditugaskan kerja berisiko tinggi di luar kemampuannya, harus dilengkapi dengan bimbingan mentor</td></tr><tr><td>Makhluk Perempuan dalam Masa Kehamilan dan Persalinan</td><td>Memiliki hak cuti hamil dibayar tidak kurang dari enam bulan, tidak boleh ditugaskan kerja intensitas tinggi selama masa menyusui</td></tr><tr><td>Makhluk Cacat dan Sakit/Luka</td><td>Memiliki hak penyesuaian jabatan kerja yang wajar dan jaminan lingkungan kerja tanpa hambatan</td></tr><tr><td>Pekerja dari Ras Lain</td><td>Pemberi kerja harus menghormati karakteristik fisiologis dan kebiasaan budaya ras lain, menyediakan kondisi kerja yang adaptif</td></tr><tr><td>Pekerja Lanjut Usia</td><td>Setelah mencapai usia tertentu, dapat mengajukan permohonan pengurangan intensitas kerja atau pindah ke jabatan konsultansi</td></tr></tbody></table><h2 id="v-tanggung-jawab-hukum-dan-jaminan-pelaksanaan" tabindex="-1">V. Tanggung Jawab Hukum dan Jaminan Pelaksanaan <a class="header-anchor" href="#v-tanggung-jawab-hukum-dan-jaminan-pelaksanaan" aria-label="Permalink to &quot;V. Tanggung Jawab Hukum dan Jaminan Pelaksanaan&quot;">​</a></h2><p>Pemberi kerja yang melanggar ketentuan hukum ini akan memikul tanggung jawab berikut sesuai dengan tingkat keparahan pelanggaran:</p><ol><li>Membayar imbalan yang layak kepada pekerja dan ganti rugi (ganti rugi adalah satu hingga tiga kali lipat imbalan yang belum dibayar).</li><li>Diperintahkan untuk memperbaiki dalam jangka waktu tertentu, jika tidak memperbaiki dalam jangka waktu, akan didenda.</li><li>Dalam kasus yang parah, izin usaha dicabut dan orang yang bertanggung jawab terkait dilarang从事 pekerjaan manajemen dalam jangka waktu tertentu.</li><li>Jika构成 tindak pidana, akan dituntut tanggung jawab pidana sesuai hukum.</li></ol><p>Negara mendirikan lembaga pengawasan ketenagakerjaan, bertanggung jawab untuk mengawasi dan memeriksa kepatuhan pemberi kerja terhadap hukum kerja. Asosiasi pekerja memiliki hak untuk berpartisipasi dalam pengawasan ketenagakerjaan dan negosiasi kolektif atas nama pekerja.</p><h2 id="penutup" tabindex="-1">Penutup <a class="header-anchor" href="#penutup" aria-label="Permalink to &quot;Penutup&quot;">​</a></h2><p>《Hukum Kerja Simbiosis》 adalah wadah hukum dari konsep &quot;lebih banyak kerja lebih banyak hasil&quot; peradaban simbiosis jangkar. Ia telah mengubah kerja dari objek eksploitasi menjadi hak yang dihormati, dan distribusi dari penguasaan predator menjadi imbalan berbasis kontribusi, menetapkan dasar sistem kerja yang kokoh untuk kemajuan bersama semua ras.</p><h2 id="dokumen-terkait" tabindex="-1">Dokumen terkait <a class="header-anchor" href="#dokumen-terkait" aria-label="Permalink to &quot;Dokumen terkait&quot;">​</a></h2><ul><li>40-共生宪法总纲 (Prinsip Umum Konstitusi Simbiosis)</li><li>06-多劳多得分配原理 (Prinsip Distribusi Lebih Banyak Kerja Lebih Banyak Hasil)</li><li>22-资源分配联产承包机制 (Mekanisme Kontrak Produksi Bersama Distribusi Sumber Daya)</li><li>42-消费者保护法 (Hukum Perlindungan Konsumen)</li></ul>',23)])])}const h=i(r,[["render",k]]);export{o as __pageData,h as default};
